"""Complete i18n overrides and round-2 patches for mkofman.com translations."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from i18n_constants import LANGS, T

ROOT = Path(__file__).resolve().parent
DATA_PATH = ROOT / "i18n_overrides_data.json"
ROUND2_JSON_PATH = ROOT / "i18n_round2_translations.json"
TRANSLATIONS_PATH = ROOT.parent / "js" / "translations.js"
GAPS_PATH = Path("/tmp/i18n_gaps.json")

# Flat key -> {lang: translation} for all 369 gap keys (generated by fill_all_translations.py)
if DATA_PATH.exists():
    OVERRIDES: dict[str, dict[str, str]] = json.loads(DATA_PATH.read_text(encoding="utf-8"))
else:
    OVERRIDES = {}


def _load_json_obj(path: Path) -> dict[str, Any]:
    raw = path.read_text(encoding="utf-8")
    start = raw.find("{")
    end = raw.rfind("}")
    return json.loads(raw[start : end + 1])


def _flatten(obj: Any, prefix: str = "") -> dict[str, str]:
    out: dict[str, str] = {}
    if isinstance(obj, dict):
        for key, val in obj.items():
            path = f"{prefix}.{key}" if prefix else key
            out.update(_flatten(val, path))
    elif isinstance(obj, str):
        out[prefix] = obj
    return out


def _gap_paths() -> set[str]:
    if not GAPS_PATH.exists():
        return set()
    gaps = json.loads(GAPS_PATH.read_text(encoding="utf-8"))
    return {f"{sec}.{key}" for sec, keys in gaps.items() for key in keys}


