def discover_round2() -> dict[str, dict[str, str]]:
    """Find translations.js keys not in gaps that are still English-identical."""
    if not TRANSLATIONS_PATH.exists():
        return dict(ROUND2)
    translations = _load_json_obj(TRANSLATIONS_PATH)
    en_flat = _flatten(translations.get("en", {}))
    gap_paths = _gap_paths()
    discovered: dict[str, dict[str, str]] = dict(ROUND2)
    for path, en_val in en_flat.items():
        if path in gap_paths or path in discovered:
            continue
        needs = False
        for lang in LANGS:
            lang_val = _flatten(translations.get(lang, {})).get(path, "")
            if lang_val == en_val:
                needs = True
                break
        if needs and path in OVERRIDES:
            discovered[path] = dict(OVERRIDES[path])
    return discovered


def write_round2_json(path: Path | None = None) -> Path:
    out = path or ROUND2_JSON_PATH
    data = discover_round2()
    out.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return out


if __name__ == "__main__":
    write_round2_json()
    print(f"Wrote {ROUND2_JSON_PATH} — {len(discover_round2())} round-2 keys")
